const playwright = require('playwright');

async function runAutomation() {
  let browser = null;

  try {
    // 1. Lanzar el navegador usando la ruta que confirmamos en Proxmox
    browser = await playwright.chromium.launch({
      executablePath: '/.n8n/nodes/node_modules/n8n-nodes-playwright/dist/nodes/browsers/chromium-1217/chrome-linux/chrome',
      args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
    });

    const context = await browser.newContext();
    const page = await context.newPage();

    // 2. Navegar al Login
    await page.goto('https://efidata.es', { 
      waitUntil: 'networkidle',
      timeout: 60000 
    });

    // 3. Aceptar Cookies (Si aparece el botón)
    try {
      await page.click('#cc-nb-ok', { timeout: 5000 });
    } catch (e) {
      // Si no aparece o ya estaba aceptada, continuamos
    }

    // 4. Rellenar credenciales
    await page.fill('input[name="username"]', 'TU_USUARIO');
    await page.fill('input[name="password"]', 'TU_PASSWORD');

    // 5. Click en Login y esperar a que cambie la URL
    await Promise.all([
      page.waitForNavigation({ waitUntil: 'networkidle' }),
      page.click('#login', { force: true })
    ]);

    // 6. Navegar a Suministros (Misma sesión activa)
    await page.goto('https://efidata.es', { 
      waitUntil: 'networkidle' 
    });

    // 7. Esperar a que la tabla de datos sea visible
    await page.waitForSelector('table', { timeout: 15000 });

    // 8. Extraer el HTML final
    const finalHtml = await page.content();

    await browser.close();

    return {
      success: true,
      html: finalHtml
    };

  } catch (error) {
    if (browser) await browser.close();

    // Devolvemos el error como string para evitar el fallo de 'stackTraceLimit' de n8n
    return {
      success: false,
      error: error.message
    };
  }
}

// n8n requiere que el retorno sea un array de objetos
const result = await runAutomation();
return [ { json: result } ];






